#!/usr/bin/env bash
# Generated by kubegen from examples/eks.yaml - re-generate instead of editing.
# Creates the eks cluster "prod-eks".
set -euo pipefail

die() { echo "error: $*" >&2; exit 1; }

# Required tools
missing=0
need() {
  command -v "$1" >/dev/null 2>&1 && return
  echo "error: required tool '$1' is not installed or not in PATH" >&2
  echo "       install it from: $2" >&2
  missing=1
}
need aws https://docs.aws.amazon.com/cli/latest/userguide/getting-started-install.html
need eksctl https://eksctl.io/installation/
need kubectl https://kubernetes.io/docs/tasks/tools/
[ "$missing" -eq 0 ] || exit 127

echo '==> Checking AWS credentials'
aws sts get-caller-identity --profile prod >/dev/null 2>&1 || die "no valid AWS credentials; run: aws configure (or aws sso login)"

echo '==> Creating EKS cluster prod-eks (this takes 15-20 minutes)'
CONFIG_FILE="$(mktemp)"
trap 'rm -f "$CONFIG_FILE"' EXIT
cat > "$CONFIG_FILE" <<'KUBEGEN_EOF'
apiVersion: eksctl.io/v1alpha5
kind: ClusterConfig
metadata:
  name: "prod-eks"
  region: "us-east-1"
  version: "1.33"
  tags:
    "env": "prod"
availabilityZones: ["us-east-1a", "us-east-1b", "us-east-1c"]
iam:
  withOIDC: true
vpc:
  cidr: "10.20.0.0/16"
  nat:
    gateway: Single
addons:
  - name: "vpc-cni"
  - name: "coredns"
  - name: "kube-proxy"
  - name: "aws-ebs-csi-driver"
managedNodeGroups:
  - name: "general"
    instanceType: "m6i.large"
    desiredCapacity: 2
    minSize: 2
    maxSize: 6
    volumeSize: 80
    privateNetworking: true
    labels:
      "workload": "general"
  - name: "spot"
    instanceType: "m6i.xlarge"
    desiredCapacity: 2
    minSize: 2
    maxSize: 2
    privateNetworking: true
    spot: true
    taints:
      - key: "spot"
        value: "true"
        effect: NoSchedule
KUBEGEN_EOF
eksctl create cluster -f "$CONFIG_FILE" \
  --profile prod

echo '==> Verifying access to prod-eks'
kubectl get nodes -o wide

echo "Cluster prod-eks is ready."
